-- Table: shap_explanations
-- Purpose: Stores individual local feature impact scores generated by TreeSHAP for each predicted risk result.

CREATE TABLE IF NOT EXISTS public.shap_explanations (
    explanation_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    result_id integer NOT NULL,
    feature_name character varying(100) NOT NULL,
    feature_value numeric,
    shap_value numeric NOT NULL,
    rank smallint NOT NULL,
    CONSTRAINT shap_explanations_result_fkey FOREIGN KEY (result_id) REFERENCES public.risk_results(result_id) ON DELETE CASCADE,
    CONSTRAINT shap_explanations_result_feature_key UNIQUE (result_id, feature_name),
    CONSTRAINT shap_explanations_result_rank_key UNIQUE (result_id, rank),
    CONSTRAINT shap_explanations_rank_check CHECK (rank >= 1)
);

CREATE INDEX IF NOT EXISTS ix_shap_explanations_result_id ON public.shap_explanations USING btree (result_id);
